def restore_native_execution_transport_parent(source,relative):
    recipe=RESTORATIONS.get(relative)
    if recipe is None:return source
    digest=lambda text:sha256(ast.unparse(ast.parse(text)).encode()).hexdigest()
    observed=digest(source)
    if observed==recipe['parent']:return source
    if observed!=recipe['current']:
        raise ValueError('Native transport differs from exact reviewed source delta: '+relative)
    restored=source
    for current,parent in recipe['edits']:
        if not current or restored.count(current)!=1:
            raise ValueError('Native transport exact delta differs: '+relative)
        restored=restored.replace(current,parent,1)
    if digest(restored)!=recipe['parent']:
        raise ValueError('Native transport complete parent restoration differs: '+relative)
    return restored
